// Package contractsentinel strictjson: fixed-field recognition shared by the
// audit submission and the stored report.
package contractsentinel

import "encoding/json"

// fixedShape describes the fixed fields of one JSON object: keys lists the
// agreed member spellings kept at this level, objects names members whose
// values are themselves objects with their own fixed shape, and arrays names
// members whose values are arrays of such objects. Members not named anywhere
// in the shape are extension data.
//
// Both entry points that decode user-supplied JSON — the audit submission and
// the stored report archive — are decoded through a fixedShape, so the
// recognition convention exists exactly once: a member denotes a fixed field
// only when its JSON-decoded name matches the agreed spelling byte for byte.
// encoding/json otherwise falls back to case-insensitive field matching, so
// an extension member such as "StAtus" would silently decode into the status
// field and could override — or launder — the conclusion carried by the
// formal "status" member, depending on where the extension member appears.
// Case variants, whitespace-padded names and unknown members never reach the
// decoder: they can neither override a formal value nor substitute for a
// missing, mistyped or unsupported one, whatever JSON type the extension
// value has. Names are compared after JSON string decoding, so a fixed name
// written with escapes still denotes that field.
type fixedShape struct {
	keys    []string
	objects map[string]fixedShape
	arrays  map[string]fixedShape
}

// strictFixedJSON rewrites data to the fixed fields of shape, at this level
// and inside every nested object member and every element of every nested
// array member named by the shape. Member order and extension members no
// longer influence the decoded values. Exact duplicate members were already
// rejected by findDuplicateJSONMember, so each kept name appears at most
// once. A null object member stays null so the decoded value keeps the same
// nil-ness as before.
func strictFixedJSON(data []byte, shape fixedShape) ([]byte, error) {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(data, &obj); err != nil {
		return nil, err
	}
	out := make(map[string]json.RawMessage, len(shape.keys))
	for _, k := range shape.keys {
		if v, ok := obj[k]; ok {
			out[k] = v
		}
	}
	for name, sub := range shape.objects {
		if raw, ok := out[name]; ok && string(raw) != "null" {
			f, err := strictFixedJSON(raw, sub)
			if err != nil {
				return nil, err
			}
			out[name] = f
		}
	}
	for name, sub := range shape.arrays {
		if raw, ok := out[name]; ok {
			f, err := strictFixedJSONArray(raw, sub)
			if err != nil {
				return nil, err
			}
			out[name] = f
		}
	}
	return json.Marshal(out)
}

// strictFixedJSONArray rewrites every element of a JSON array with
// strictFixedJSON. A null array stays null so the decoded slice keeps the
// same nil-ness as before.
func strictFixedJSONArray(raw json.RawMessage, shape fixedShape) (json.RawMessage, error) {
	var elems []json.RawMessage
	if err := json.Unmarshal(raw, &elems); err != nil {
		return nil, err
	}
	if elems == nil {
		return raw, nil
	}
	out := make([]json.RawMessage, 0, len(elems))
	for _, e := range elems {
		f, err := strictFixedJSON(e, shape)
		if err != nil {
			return nil, err
		}
		out = append(out, f)
	}
	return json.Marshal(out)
}

// Package contractsentinel jsonwalk: the structural walk over a JSON document
// shared by the duplicate-member check and the character-legality check.
//
// Both checks must reach exactly the same values — every object member name
// and every string value, at every depth, including content nested under
// unknown extension members — so the layer-by-layer recognition of objects
// and arrays, and the path that locates each value, is defined exactly once
// here. The checks themselves (which names repeat inside one object, which
// characters a string literal may contain) stay in their own files and plug
// into this walk as hooks.
package contractsentinel

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// jsonPathStep locates one level of a JSON value: a member step when the
// value was reached through an object member, or an index step when it is an
// element of an array.
type jsonPathStep struct {
	key   string // member name for an object step; "" for an array step
	index int    // 0-based array index for an array step; -1 for an object step
}

// jsonWalkHooks receives the events of one structural walk over a JSON
// document. Every path slice is owned by the walk and reused for later
// events; a hook that retains a path must copy it. memberName and
// stringValue return true to stop the walk immediately, which is how a check
// reports its first problem.
type jsonWalkHooks struct {
	// enterObject fires right after an object's opening brace; path locates
	// the object itself.
	enterObject func(path []jsonPathStep)
	// exitObject fires after the matching object's closing brace.
	exitObject func(path []jsonPathStep)
	// memberName fires for every object member name. path locates the
	// containing object (not the member), name is the decoded member name,
	// and start/end bound the raw name token in the input.
	memberName func(path []jsonPathStep, name string, start, end int) (stop bool)
	// stringValue fires for every string that is a value, never a member
	// name. path locates the value and start/end bound the raw string token.
	stringValue func(path []jsonPathStep, start, end int) (stop bool)
}

// walkJSONTokens scans data structurally once, firing hooks for every object,
// member name and string value at every depth: the top-level value, nested
// objects, array elements and the contents of unknown extension members
// alike. String values are consumed atomically by the decoder, so text inside
// a string that looks like JSON is ordinary content and never produces
// events. Number literals are kept as text so an oversized exponent cannot
// abort the walk; scalar values themselves are irrelevant to both checks.
// Member names are compared after JSON string decoding, so a name written
// literally and the same name written with Unicode escapes are the same name.
//
// The walk is best-effort over syntax: a decoder error stops it quietly,
// because json.Unmarshal remains the single source of syntax errors and runs
// right after these scans.
func walkJSONTokens(data []byte, hooks jsonWalkHooks) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	walkJSONValue(dec, nil, hooks)
}

// walkJSONValue consumes exactly one JSON value from dec, firing the hooks at
// and below it. path locates the value within its document. It reports true
// when the walk stopped, either because a hook asked to stop or because the
// input turned out to be malformed.
func walkJSONValue(dec *json.Decoder, path []jsonPathStep, hooks jsonWalkHooks) (stop bool) {
	start := int(dec.InputOffset())
	tok, err := dec.Token()
	if err != nil {
		return true // malformed JSON: defer to json.Unmarshal
	}
	end := int(dec.InputOffset())
	switch v := tok.(type) {
	case string:
		if hooks.stringValue != nil {
			return hooks.stringValue(path, start, end)
		}
		return false
	case json.Delim:
		switch v {
		case '{':
			if hooks.enterObject != nil {
				hooks.enterObject(path)
			}
			for dec.More() {
				keyStart := int(dec.InputOffset())
				keyTok, err := dec.Token()
				if err != nil {
					return true // malformed JSON: defer
				}
				keyEnd := int(dec.InputOffset())
				// Between More() and the value, Token can only be a member name.
				key, _ := keyTok.(string)
				if hooks.memberName != nil && hooks.memberName(path, key, keyStart, keyEnd) {
					return true
				}
				child := append(append([]jsonPathStep(nil), path...), jsonPathStep{key: key, index: -1})
				if walkJSONValue(dec, child, hooks) {
					return true
				}
			}
			if _, err := dec.Token(); err != nil { // consume '}'
				return true // malformed JSON: defer
			}
			if hooks.exitObject != nil {
				hooks.exitObject(path)
			}
			return false
		case '[':
			for i := 0; dec.More(); i++ {
				child := append(append([]jsonPathStep(nil), path...), jsonPathStep{index: i})
				if walkJSONValue(dec, child, hooks) {
					return true
				}
			}
			if _, err := dec.Token(); err != nil { // consume ']'
				return true // malformed JSON: defer
			}
			return false
		}
	}
	// '}' and ']' are consumed by the enclosing object or array and never
	// start a value; numbers, booleans and null are complete scalars.
	return false
}

// renderJSONPath renders schema-free path steps as ".key" and "[index]".
func renderJSONPath(path []jsonPathStep) string {
	var b strings.Builder
	for _, step := range path {
		if step.index >= 0 {
			fmt.Fprintf(&b, "[%d]", step.index)
		} else {
			b.WriteByte('.')
			b.WriteString(step.key)
		}
	}
	return b.String()
}

// Package contractsentinel diff: deterministic comparison of two stored reports.
package contractsentinel

import (
	"sort"
)

// Per-rule comparison outcomes.
const (
	ChangeNewDefect      = "新发现缺陷"
	ChangeResolvedDefect = "已消除缺陷"
	ChangeStatusChanged  = "检查状态变化"
	ChangeNoteChanged    = "检查说明变化"
	ChangeNoChange       = "无变化"
	ChangeRuleAdded      = "新增规则"
	ChangeRuleRemoved    = "移除规则"
	ChangeRuleChanged    = "规则变化"
)

// DiffReportRef identifies one side of a diff: the report id and the artifact
// name and content hash it audited.
type DiffReportRef struct {
	ReportID string         `json:"reportId"`
	Artifact ReportArtifact `json:"artifact"`
}

// DiffSide is one side of a per-rule comparison: the complete rule definition
// with its check status, and the defect evidence when the rule found a defect.
// The finding keeps the artifact hash and rule version recorded at audit time.
type DiffSide struct {
	Rule    ReportRule     `json:"rule"`
	Finding *ReportFinding `json:"finding"`
}

// RuleDiff is the comparison result for one rule id. Exactly one result is
// emitted per rule id present on either side; a side absent from that report
// is null.
type RuleDiff struct {
	RuleID string    `json:"ruleId"`
	Change string    `json:"change"`
	Before *DiffSide `json:"before"`
	After  *DiffSide `json:"after"`
}

// DiffSummary counts every result category plus the actual defect totals of
// both sides. Zero counts are always present.
type DiffSummary struct {
	NewDefects      int `json:"newDefects"`
	ResolvedDefects int `json:"resolvedDefects"`
	StatusChanges   int `json:"statusChanges"`
	NoteChanges     int `json:"noteChanges"`
	NoChange        int `json:"noChange"`
	AddedRules      int `json:"addedRules"`
	RemovedRules    int `json:"removedRules"`
	ChangedRules    int `json:"changedRules"`
	BeforeDefects   int `json:"beforeDefects"`
	AfterDefects    int `json:"afterDefects"`
}

// DiffResult is the full comparison of two reports. It contains no timestamps
// and no storage-order artifacts, so comparing the same pair of reports always
// renders byte-identical JSON.
type DiffResult struct {
	Before              DiffReportRef `json:"before"`
	After               DiffReportRef `json:"after"`
	ArtifactNameChanged bool          `json:"artifactNameChanged"`
	ArtifactHashChanged bool          `json:"artifactHashChanged"`
	Results             []RuleDiff    `json:"results"`
	Summary             DiffSummary   `json:"summary"`
}

// validReportID reports whether id is exactly 64 lowercase hex characters.
func validReportID(id string) bool {
	if len(id) != 64 {
		return false
	}
	for _, c := range id {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// LoadReportForDiff loads a stored report for comparison. The id must be 64
// lowercase hex characters; the archive is fully verified. The store is only
// read, never created or modified.
func LoadReportForDiff(dir, id string) (Report, error) {
	if !validReportID(id) {
		return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
	}
	return LoadReport(dir, id)
}

// DiffStore loads both reports from the store and compares them. Both reports
// are fully verified before any comparison happens; any failure yields an
// error and no partial result.
func DiffStore(dir, beforeID, afterID string) (DiffResult, error) {
	before, err := LoadReportForDiff(dir, beforeID)
	if err != nil {
		return DiffResult{}, err
	}
	after, err := LoadReportForDiff(dir, afterID)
	if err != nil {
		return DiffResult{}, err
	}
	return DiffReports(before, after), nil
}

// sameRuleDefinition reports whether two rules with the same id also agree on
// version, kind, severity, invariant and ABI requirement. Only then may their
// check statuses be compared.
func sameRuleDefinition(a, b ReportRule) bool {
	return a.Version == b.Version &&
		a.Kind == b.Kind &&
		a.Severity == b.Severity &&
		a.Invariant == b.Invariant &&
		a.RequiresABI == b.RequiresABI
}

// indexFindings maps rule id to finding. Reports are verified before diffing,
// so at most one finding exists per rule id.
func indexFindings(findings []ReportFinding) map[string]ReportFinding {
	out := make(map[string]ReportFinding, len(findings))
	for _, f := range findings {
		out[f.RuleID] = f
	}
	return out
}

// diffSide builds one side of a result: the rule and, when it found a defect,
// its evidence.
func diffSide(rule ReportRule, findings map[string]ReportFinding) *DiffSide {
	side := &DiffSide{Rule: rule}
	if f, ok := findings[rule.ID]; ok {
		finding := f
		side.Finding = &finding
	}
	return side
}

// DiffReports compares two verified reports. Rules are matched by id; statuses
// are only compared when the full rule definition is identical. Results are
// sorted by rule id and independent of the storage order of rules and
// findings.
func DiffReports(before, after Report) DiffResult {
	beforeRules := make(map[string]ReportRule, len(before.Rules))
	for _, r := range before.Rules {
		beforeRules[r.ID] = r
	}
	afterRules := make(map[string]ReportRule, len(after.Rules))
	for _, r := range after.Rules {
		afterRules[r.ID] = r
	}
	beforeFindings := indexFindings(before.Findings)
	afterFindings := indexFindings(after.Findings)

	ids := make([]string, 0, len(beforeRules)+len(afterRules))
	for id := range beforeRules {
		ids = append(ids, id)
	}
	for id := range afterRules {
		if _, ok := beforeRules[id]; !ok {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)

	result := DiffResult{
		Before:              DiffReportRef{ReportID: before.ReportID, Artifact: before.Artifact},
		After:               DiffReportRef{ReportID: after.ReportID, Artifact: after.Artifact},
		ArtifactNameChanged: before.Artifact.Name != after.Artifact.Name,
		ArtifactHashChanged: before.Artifact.Hash != after.Artifact.Hash,
		Results:             []RuleDiff{},
		Summary: DiffSummary{
			BeforeDefects: len(before.Findings),
			AfterDefects:  len(after.Findings),
		},
	}
	for _, id := range ids {
		b, inBefore := beforeRules[id]
		a, inAfter := afterRules[id]
		entry := RuleDiff{RuleID: id}
		switch {
		case !inBefore:
			entry.Change = ChangeRuleAdded
			entry.After = diffSide(a, afterFindings)
			result.Summary.AddedRules++
		case !inAfter:
			entry.Change = ChangeRuleRemoved
			entry.Before = diffSide(b, beforeFindings)
			result.Summary.RemovedRules++
		case !sameRuleDefinition(b, a):
			entry.Change = ChangeRuleChanged
			entry.Before = diffSide(b, beforeFindings)
			entry.After = diffSide(a, afterFindings)
			result.Summary.ChangedRules++
		default:
			entry.Before = diffSide(b, beforeFindings)
			entry.After = diffSide(a, afterFindings)
			switch {
			case b.Status == a.Status && b.Note == a.Note:
				entry.Change = ChangeNoChange
				result.Summary.NoChange++
			case b.Status == a.Status:
				entry.Change = ChangeNoteChanged
				result.Summary.NoteChanges++
			case b.Status == StatusPass && a.Status == StatusDefect:
				entry.Change = ChangeNewDefect
				result.Summary.NewDefects++
			case b.Status == StatusDefect && a.Status == StatusPass:
				entry.Change = ChangeResolvedDefect
				result.Summary.ResolvedDefects++
			default:
				entry.Change = ChangeStatusChanged
				result.Summary.StatusChanges++
			}
		}
		result.Results = append(result.Results, entry)
	}
	return result
}

