93	// expectCorruptRequiresABILoad asserts the full read-side contract for an
94	// illegal formal requiresABI value: errCorrupt naming the report id, the
95	// offending rule and the boolean requirement, a zero report and an untouched
96	// archive.
97	func expectCorruptRequiresABILoad(t *testing.T, dir, id, rule string) {
98		t.Helper()
99		path := filepath.Join(dir, id+".json")
100		before, err := os.ReadFile(path)
101		if err != nil {
102			t.Fatal(err)
103		}
104		got, err := LoadReport(dir, id)
105		if err == nil {
106			t.Fatalf("a non-boolean formal requiresABI must reject the whole archive, got %+v", got)
107		}
108		var ec errCorrupt
109		if !errors.As(err, &ec) {
110			t.Fatalf("illegal requiresABI classifies as errCorrupt, got %T: %v", err, err)
111		}
112		msg := err.Error()
113		if !strings.Contains(msg, id) {
114			t.Fatalf("error must name the report id %q: %v", id, err)
115		}
116		if !strings.Contains(msg, rule) {
117			t.Fatalf("error must name the offending rule %q: %v", rule, err)
118		}
119		if !strings.Contains(msg, "requiresABI must be a boolean") {
120			t.Fatalf("error must state requiresABI must be a boolean: %v", err)
121		}
122		if !reflect.DeepEqual(got, Report{}) {
123			t.Fatalf("failed read must return the zero report, got %+v", got)
124		}
125		after, err := os.ReadFile(path)
126		if err != nil {
127			t.Fatalf("corrupt archive must not be deleted: %v", err)
128		}
129		if string(after) != string(before) {
130			t.Fatal("failed read must not rewrite or repair the archive")
131		}
132	}
