143				{ID: "r-unchecked", Kind: "symbolic", Severity: "info", Invariant: "inv-unchecked", Version: "3", Status: StatusUnchecked},
144				{ID: "r-tool", Kind: "static", Severity: "medium", Invariant: "inv-tool", RequiresABI: true, Version: "4", Status: StatusToolMissing, Note: "符号执行引擎未安装"},
145				{ID: "r-timeout", Kind: "symbolic", Severity: "critical", Invariant: "inv-timeout", Version: "5", Status: StatusTimeout, Note: "超过 60s 截止时间"},
