func TestDiffStoreRejectsBadStringMemberEitherSide(t *testing.T) {
	dir := t.TempDir()
	good := oneDefectFixture()
	goodID := writeReportWithFreshID(t, dir, good)

	// 另一侧是另一份合法报告（多一条规则），损坏后落盘；null 会被洗成
